selector.text:
import { Command as CommanderCommand } from "commander";
import { resolve } from "node:path";
import type { DaemonCommandName } from "@symnav/daemon";
import type { InvocationRoute, SelectedInvocation } from "./invocation-route.js";

type WorkspaceCommandName = Exclude<DaemonCommandName, "help" | "version" | "unknown">;

const workspaceCommandNames = {
  overview: "overview",
  resolve: "resolve",
  def: "def",
  refs: "refs",
  context: "context",
  graph: "graph",
  stats: "stats",
} as const satisfies Readonly<Record<WorkspaceCommandName, WorkspaceCommandName>>;

export class InvocationWorkspaceSelector {
  classify(argv: readonly string[], cwd: string): InvocationRoute {
    return this.select(argv, cwd).route;
  }

  select(argv: readonly string[], cwd: string): SelectedInvocation {
    const parsed = new CommanderCommand()
      .helpOption(false)
      .allowUnknownOption(true)
      .allowExcessArguments(true)
      .option("--cwd <dir>")
      .option("-h, --help")
      .option("-v, --version")
      .argument("[command]")
      .argument("[arguments...]")
      .parse([...argv], { from: "user" });
    const [command, action] = parsed.args;
    const options = parsed.opts<{
      cwd?: string;
      help?: boolean;
      version?: boolean;
    }>();

    if (options.help === true) {
      return { route: { kind: "local", commandName: "help" }, argv };
    }
    if (options.version === true) {
      return { route: { kind: "local", commandName: "version" }, argv };
    }
    if (command === "daemon" && (action === "start" || action === "status" || action === "stop")) {
      return { route: { kind: "control", action }, argv };
    }
    const commandName = InvocationWorkspaceSelector.workspaceCommandName(command);
    if (commandName === undefined) {
      return { route: { kind: "local", commandName: "unknown" }, argv };
    }
    const cwdOverride = options.cwd;
    const startDirectory = cwdOverride === undefined ? cwd : resolve(cwd, cwdOverride);
    return {
      route: { kind: "workspace", commandName, startDirectory },
      argv:
        cwdOverride === undefined
          ? argv
          : InvocationWorkspaceSelector.rewriteEffectiveCwd(argv, startDirectory),
    };
  }

  private static workspaceCommandName(
    command: string | undefined,
  ): WorkspaceCommandName | undefined {
    if (command === undefined || !Object.hasOwn(workspaceCommandNames, command)) return undefined;
    return workspaceCommandNames[command as WorkspaceCommandName];
  }

  private static rewriteEffectiveCwd(argv: readonly string[], startDir: string): readonly string[] {
    const separatorIndex = argv.indexOf("--");
    const optionsEnd = separatorIndex === -1 ? argv.length : separatorIndex;
    let optionIndex: number | undefined;
    let valueIndex: number | undefined;
    for (let index = 0; index < optionsEnd; index += 1) {
      const argument = argv[index];
      if (argument === "--cwd" && index + 1 < optionsEnd) {
        optionIndex = index;
        valueIndex = index + 1;
        index += 1;
      } else if (argument?.startsWith("--cwd=")) {
        optionIndex = index;
        valueIndex = undefined;
      }
    }
    if (optionIndex === undefined) return argv;
    return argv.map((argument, index) => {
      if (index === valueIndex) return startDir;
      if (index === optionIndex && valueIndex === undefined) return `--cwd=${startDir}`;
      return argument;
    });
  }
}

coordinator.text:
import type { DaemonClient, DaemonClientExecuteResult } from "@symnav/daemon";
import type { CliProgramExecutor } from "./cli-program-executor.js";
import type { CliExecutionRequest } from "./command-execution-result.js";
import { InvocationWorkspaceSelector } from "./invocation-workspace-selector.js";

export interface CliInvocationCoordinatorOptions {
  readonly daemonClient: DaemonClient;
  readonly createLocalExecutor: () => CliProgramExecutor;
  readonly resolveWorkspaceRoot: (startDirectory: string) => Promise<string>;
}

export class CliInvocationCoordinator {
  private readonly selector = new InvocationWorkspaceSelector();

  constructor(private readonly options: CliInvocationCoordinatorOptions) {}

  async execute(request: CliExecutionRequest): Promise<DaemonClientExecuteResult> {
    const selected = this.selector.select(request.argv, request.cwd);
    if (selected.route.kind !== "workspace") {
      return this.executeLocally(request);
    }
    const workspaceRequest: CliExecutionRequest = { ...request, argv: selected.argv };
    let workspaceRoot: string;
    try {
      workspaceRoot = await this.options.resolveWorkspaceRoot(selected.route.startDirectory);
    } catch {
      return this.executeLocally(workspaceRequest);
    }
    return this.options.daemonClient.execute({
      workspaceRoot,
      commandName: selected.route.commandName,
      argv: selected.argv,
      cwd: request.cwd,
      telemetryEnabled: request.telemetryEnabled,
    });
  }

  private async executeLocally(request: CliExecutionRequest): Promise<DaemonClientExecuteResult> {
    const result = await this.options
      .createLocalExecutor()
      .execute({ ...request, executionMode: "cold" });
    return { mode: "cold", result };
  }
}

executor.text:
import { DaemonDiagnosticValues, type DaemonDiagnostics } from "./daemon-diagnostics.js";

export type DaemonExecutionMode = "cold" | "warm" | "fallback";
export type DaemonOutputStream = "stdout" | "stderr";

export interface DaemonExecutorRequest {
  readonly argv: readonly string[];
  readonly cwd: string;
  readonly telemetryEnabled: boolean;
  readonly executionMode: DaemonExecutionMode;
}

export interface DaemonOutputRecord {
  readonly stream: DaemonOutputStream;
  readonly bytes: Uint8Array;
}

export interface DaemonSequencedOutputRecord extends DaemonOutputRecord {
  readonly sequence: number;
}

export interface DaemonOutputSink {
  append(record: DaemonSequencedOutputRecord): Promise<void>;
}

export interface DaemonExecutorOutput {
  records(): AsyncIterable<DaemonOutputRecord>;
  dispose(): Promise<void>;
}

export interface DaemonExecutorInitializationResult {
  readonly fileCount: number;
  readonly diagnostics?: DaemonDiagnostics;
}

export interface DaemonExecutorExecutionResult {
  readonly exitCode: number;
  readonly output: DaemonExecutorOutput;
  readonly diagnostics?: DaemonDiagnostics;
}

export interface DaemonExecutor {
  initialize(workspaceRoot: string): Promise<DaemonExecutorInitializationResult>;
  execute(request: DaemonExecutorRequest): Promise<DaemonExecutorExecutionResult>;
  releaseTransientResources(): Promise<void>;
}

export interface DaemonExecutorFactoryOptions {
  readonly stateDirectory: string;
  readonly productVersion: string;
  readonly sampleResources: () => void;
}

export type DaemonExecutorFactory = (
  options: DaemonExecutorFactoryOptions,
) => DaemonExecutor | Promise<DaemonExecutor>;

export interface DaemonExecutorModule {
  readonly createDaemonExecutor: DaemonExecutorFactory;
}

export type DaemonExecutorModuleUrl = string;

class ValidatedDaemonExecutorOutput implements DaemonExecutorOutput {
  constructor(private readonly output: DaemonExecutorOutput) {}

  async *records(): AsyncIterable<DaemonOutputRecord> {
    for await (const value of this.output.records()) {
      if (!DaemonExecutorValidation.isOutputRecord(value)) {
        throw new Error("Invalid daemon executor output record");
      }
      yield value;
    }
  }

  dispose(): Promise<void> {
    return this.output.dispose();
  }
}

class ValidatedDaemonExecutor implements DaemonExecutor {
  constructor(private readonly executor: DaemonExecutor) {}

  async initialize(workspaceRoot: string): Promise<DaemonExecutorInitializationResult> {
    const result: unknown = await this.executor.initialize(workspaceRoot);
    if (!DaemonExecutorValidation.isInitializationResult(result)) {
      throw new Error("Invalid daemon executor initialization result");
    }
    return result;
  }

  async execute(request: DaemonExecutorRequest): Promise<DaemonExecutorExecutionResult> {
    const result: unknown = await this.executor.execute(request);
    if (!DaemonExecutorValidation.isExecutionResult(result)) {
      throw new Error("Invalid daemon executor execution result");
    }
    return { ...result, output: new ValidatedDaemonExecutorOutput(result.output) };
  }

  releaseTransientResources(): Promise<void> {
    return this.executor.releaseTransientResources();
  }
}

class DaemonExecutorModuleImporter {
  private static readonly hostImporterModuleUrl = [
    "data:text/javascript",
    "export default moduleUrl => import(moduleUrl)",
  ].join(",");

  public static async load(moduleUrl: DaemonExecutorModuleUrl): Promise<unknown> {
    const importer = await import(this.hostImporterModuleUrl);
    return importer.default(moduleUrl) as Promise<unknown>;
  }
}

export class DaemonExecutorModuleLoader {
  static async load(
    moduleUrl: DaemonExecutorModuleUrl,
    options: DaemonExecutorFactoryOptions,
  ): Promise<DaemonExecutor> {
    if (!DaemonExecutorValidation.isFileUrl(moduleUrl)) {
      throw new Error("Daemon executor module must use a file URL");
    }
    const loaded = await DaemonExecutorModuleImporter.load(moduleUrl);
    if (
      !DaemonExecutorValidation.isRecord(loaded) ||
      typeof loaded.createDaemonExecutor !== "function"
    ) {
      throw new Error("Daemon executor module has no createDaemonExecutor factory");
    }
    const executor: unknown = await loaded.createDaemonExecutor(options);
    if (!DaemonExecutorValidation.isExecutor(executor)) {
      throw new Error("Daemon executor factory returned an invalid executor");
    }
    return new ValidatedDaemonExecutor(executor);
  }
}

class DaemonExecutorValidation {
  static isInitializationResult(value: unknown): value is DaemonExecutorInitializationResult {
    if (!this.isRecord(value)) return false;
    return (
      this.hasExactKeys(value, this.keysWithDiagnostics(["fileCount"], value)) &&
      this.isCount(value.fileCount) &&
      this.isDiagnostics(value.diagnostics)
    );
  }

  static isExecutionResult(value: unknown): value is DaemonExecutorExecutionResult {
    if (!this.isRecord(value)) return false;
    return (
      this.hasExactKeys(value, this.keysWithDiagnostics(["exitCode", "output"], value)) &&
      this.isCount(value.exitCode) &&
      this.isOutput(value.output) &&
      this.isDiagnostics(value.diagnostics)
    );
  }

  static isOutputRecord(value: unknown): value is DaemonOutputRecord {
    return (
      this.isRecord(value) &&
      this.hasExactKeys(value, ["stream", "bytes"]) &&
      (value.stream === "stdout" || value.stream === "stderr") &&
      value.bytes instanceof Uint8Array
    );
  }

  static isFileUrl(value: unknown): value is DaemonExecutorModuleUrl {
    return typeof value === "string" && value.startsWith("file://");
  }

  static isExecutor(value: unknown): value is DaemonExecutor {
    return (
      this.isRecord(value) &&
      typeof value.initialize === "function" &&
      typeof value.execute === "function" &&
      typeof value.releaseTransientResources === "function"
    );
  }

  private static isOutput(value: unknown): value is DaemonExecutorOutput {
    return (
      this.isRecord(value) &&
      typeof value.records === "function" &&
      typeof value.dispose === "function"
    );
  }

  private static isDiagnostics(value: unknown): value is DaemonDiagnostics | undefined {
    return value === undefined || DaemonDiagnosticValues.isDiagnostics(value);
  }

  private static keysWithDiagnostics(
    keys: readonly string[],
    value: Record<string, unknown>,
  ): readonly string[] {
    return value.diagnostics === undefined ? keys : [...keys, "diagnostics"];
  }

  private static hasExactKeys(value: Record<string, unknown>, keys: readonly string[]): boolean {
    const actual = Object.keys(value).sort();
    const expected = [...keys].sort();
    return (
      actual.length === expected.length && actual.every((key, index) => key === expected[index])
    );
  }

  private static isCount(value: unknown): value is number {
    return Number.isSafeInteger(value) && Number(value) >= 0;
  }

  static isRecord(value: unknown): value is Record<string, unknown> {
    return typeof value === "object" && value !== null && !Array.isArray(value);
  }
}

render.text:
import type { DaemonStartResult, DaemonStopResult, RunningDaemonStatus } from "@symnav/daemon";

export class DaemonLifecycleRenderer {
  static renderStartText(result: DaemonStartResult): string {
    if (result.status === "ready") {
      return `Daemon ready for ${result.workspaceRoot}\n${result.fileCount} files loaded in ${DaemonLifecycleRenderer.duration(result.loadDurationMs)}\n`;
    }
    if (result.status === "already-running") {
      return `Daemon already running for ${result.workspaceRoot} (pid ${result.pid}, up ${DaemonLifecycleRenderer.uptime(result.uptimeMs)})\n`;
    }
    return "Daemon disabled by SYMNAV_DAEMON=0\n";
  }

  static renderStartJson(result: DaemonStartResult): string {
    return `${JSON.stringify(result)}\n`;
  }

  static renderStatusText(results: readonly RunningDaemonStatus[]): string {
    if (results.length === 0) return "No daemons running.\n";
    return `${results.map((result) => DaemonLifecycleRenderer.statusLine(result)).join("\n")}\n`;
  }

  static renderStatusJson(results: readonly RunningDaemonStatus[]): string {
    return `${JSON.stringify({ schemaVersion: 1, daemons: results })}\n`;
  }

  static renderStopText(result: DaemonStopResult): string {
    if (result.status === "not-running") {
      return `No daemon running for ${result.workspaceRoot}\n`;
    }
    if (result.status === "killed") {
      return `Killed daemon for ${result.workspaceRoot} (pid ${result.pid})\n`;
    }
    return `Stopped daemon for ${result.workspaceRoot} (pid ${result.pid})\n`;
  }

  static renderStopJson(result: DaemonStopResult): string {
    return `${JSON.stringify(result)}\n`;
  }

  private static statusLine(result: RunningDaemonStatus): string {
    if (result.state === "starting") {
      const memory =
        result.memoryBytes === undefined
          ? ""
          : `  ${DaemonLifecycleRenderer.bytes(result.memoryBytes)}`;
      return `${result.workspaceRoot}  pid ${result.pid}  starting ${DaemonLifecycleRenderer.uptime(result.startupElapsedMs)}${memory}`;
    }
    const prefix = `${result.workspaceRoot}  pid ${result.pid}  up ${DaemonLifecycleRenderer.uptime(result.uptimeMs)}`;
    if (result.state === "unresponsive") return `${prefix}  unresponsive`;
    if (result.state === "busy") {
      return `${prefix}  busy ${result.command}  ${DaemonLifecycleRenderer.uptime(result.elapsedMs)}  queued ${result.queued}  ${DaemonLifecycleRenderer.bytes(result.memoryBytes)}`;
    }
    if (result.state === "recovering") {
      return `${prefix}  recovering ${result.detail}  queued ${result.queued}  ${DaemonLifecycleRenderer.bytes(result.memoryBytes)}`;
    }
    const fileCount = `${result.fileCount} files`;
    const memory = DaemonLifecycleRenderer.bytes(result.memoryBytes);
    const lastRequest =
      result.lastRequestAgoMs === undefined
        ? "no requests"
        : `last request ${DaemonLifecycleRenderer.uptime(result.lastRequestAgoMs)} ago`;
    return `${prefix}  ready  ${fileCount}  ${memory}  ${lastRequest}`;
  }

  private static duration(durationMs: number): string {
    if (durationMs < 1_000) return `${Math.max(0, Math.round(durationMs))}ms`;
    return `${(durationMs / 1_000).toFixed(1)}s`;
  }

  private static uptime(uptimeMs: number): string {
    const seconds = Math.max(0, Math.floor(uptimeMs / 1_000));
    if (seconds < 60) return `${seconds}s`;
    const minutes = Math.floor(seconds / 60);
    if (minutes < 60) return `${minutes}m`;
    return `${Math.floor(minutes / 60)}h`;
  }

  private static bytes(bytes: number): string {
    const units = ["B", "KB", "MB", "GB"];
    let value = Math.max(0, bytes);
    let unit = 0;
    while (value >= 1024 && unit < units.length - 1) {
      value /= 1024;
      unit += 1;
    }
    const precision = value >= 10 || unit === 0 || Number.isInteger(value) ? 0 : 1;
    return `${value.toFixed(precision)} ${units[unit]}`;
  }
}

state-directory.text:
import { existsSync, realpathSync } from "node:fs";
import { homedir } from "node:os";
import { basename, dirname, join, resolve } from "node:path";

export class StateDirectoryResolver {
  constructor(
    private readonly environment: NodeJS.ProcessEnv = process.env,
    private readonly homeDirectory: string = homedir(),
  ) {}

  resolve(): string {
    const configuredDirectory =
      this.environment.SYMNAV_STATE_DIR ?? join(this.homeDirectory, ".symnav");
    return StateDirectoryResolver.canonicalize(configuredDirectory);
  }

  static canonicalize(stateDirectory: string): string {
    const absoluteDirectory = resolve(stateDirectory);
    const missingSegments: string[] = [];
    let existingAncestor = absoluteDirectory;
    while (!existsSync(existingAncestor)) {
      const parent = dirname(existingAncestor);
      if (parent === existingAncestor) return absoluteDirectory;
      missingSegments.unshift(basename(existingAncestor));
      existingAncestor = parent;
    }
    return join(realpathSync(existingAncestor), ...missingSegments);
  }
}

protocol.text:
import type { DaemonCommandName, DaemonExecutorRequest, DaemonOutputStream } from "@symnav/daemon";
import type { DaemonRejectedExecutionFrame } from "../daemon-admission.js";
import type { DaemonExecutionFailureCode } from "../daemon-execution-failure.js";
import type { CompletionSpoolManifest } from "../delivery/completion-spool.js";

export const DAEMON_PROTOCOL_VERSION = 5;
export const DAEMON_RECORD_SCHEMA_VERSION = 2;
export const DAEMON_DIAGNOSTIC_SCHEMA_VERSION = 1;

export interface DaemonIdentityCoordinates {
  readonly workspaceRoot: string;
  readonly workspaceKey: string;
  readonly stateKey: string;
  readonly identityKey: string;
  readonly instanceId: string;
  readonly processToken: string;
  readonly endpoint: string;
}

export interface DaemonRecord extends DaemonIdentityCoordinates {
  readonly schemaVersion: number;
  readonly protocolVersion: number;
  readonly symnavVersion: string;
  readonly pid: number;
  readonly state: "starting" | "ready";
  readonly startedAt: number;
  readonly readyAt?: number;
  readonly lastNavigationAt?: number;
  readonly fileCount?: number;
  readonly memoryBytes?: number;
  readonly memoryCapBytes: number;
}

export interface DaemonActivitySnapshot {
  readonly lifecycle: "starting" | "ready" | "busy" | "recovering" | "draining";
  readonly recoveryDetail?: "resource-pressure" | "worker-replacement";
  readonly pid: number;
  readonly startedAt: number;
  readonly startupElapsedMs: number;
  readonly fileCount?: number;
  readonly processRssBytes: number;
  readonly hardProcessRssBytes: number;
  readonly workerHeapUsedBytes?: number;
  readonly workerGeneration: number;
  readonly current?: {
    readonly requestId: string;
    readonly command: DaemonCommandName;
    readonly elapsedMs: number;
  };
  readonly queued: number;
  readonly lastCompletedAgoMs?: number;
  readonly spoolBytes: number;
}

export type RunningDaemonStatus =
  | {
      readonly state: "starting";
      readonly workspaceRoot: string;
      readonly pid: number;
      readonly startupElapsedMs: number;
      readonly memoryBytes?: number;
    }
  | {
      readonly state: "ready";
      readonly workspaceRoot: string;
      readonly pid: number;
      readonly uptimeMs: number;
      readonly fileCount: number;
      readonly memoryBytes: number;
      readonly lastRequestAgoMs?: number;
    }
  | {
      readonly state: "busy";
      readonly workspaceRoot: string;
      readonly pid: number;
      readonly uptimeMs: number;
      readonly command: DaemonCommandName;
      readonly elapsedMs: number;
      readonly queued: number;
      readonly memoryBytes: number;
    }
  | {
      readonly state: "recovering";
      readonly workspaceRoot: string;
      readonly pid: number;
      readonly uptimeMs: number;
      readonly detail: "resource-pressure" | "worker-replacement" | "draining";
      readonly queued: number;
      readonly memoryBytes: number;
    }
  | {
      readonly state: "unresponsive";
      readonly workspaceRoot: string;
      readonly pid: number;
      readonly uptimeMs: number;
      readonly lastResponseAgoMs?: number;
      readonly lastKnown?: DaemonActivitySnapshot;
    };

export interface DaemonStatusEnvelope {
  readonly schemaVersion: 1;
  readonly daemons: readonly RunningDaemonStatus[];
}

export type DaemonStopResult =
  | { readonly status: "stopped"; readonly workspaceRoot: string; readonly pid: number }
  | { readonly status: "killed"; readonly workspaceRoot: string; readonly pid: number }
  | { readonly status: "not-running"; readonly workspaceRoot: string };

export type DaemonStopReason = "graceful" | "idle" | "resource" | "workspace-deleted";

export interface DaemonExecuteRequest {
  readonly kind: "execute";
  readonly protocolVersion: number;
  readonly instanceId: string;
  readonly processToken: string;
  readonly requestId: string;
  readonly commandName: DaemonCommandName;
  readonly request: DaemonExecutorRequest;
}

export type DaemonExecutionServerFrame =
  | {
      readonly kind: "accepted";
      readonly instanceId: string;
      readonly processToken: string;
      readonly requestId: string;
      readonly acceptedAt: number;
      readonly queuePosition: number;
    }
  | DaemonRejectedExecutionFrame
  | {
      readonly kind: "result-manifest";
      readonly instanceId: string;
      readonly processToken: string;
      readonly requestId: string;
      readonly manifest: CompletionSpoolManifest;
    }
  | {
      readonly kind: "result-end";
      readonly instanceId: string;
      readonly processToken: string;
      readonly requestId: string;
      readonly transferId: string;
      readonly rawBytes: number;
      readonly recordCount: number;
      readonly sha256: string;
    }
  | {
      readonly kind: "execution-failed";
      readonly instanceId: string;
      readonly processToken: string;
      readonly requestId: string;
      readonly code: DaemonExecutionFailureCode;
    };

export type DaemonExecutionStatus =
  | { readonly state: "unknown" }
  | { readonly state: "queued"; readonly queuePosition: number }
  | { readonly state: "running"; readonly startedAt: number }
  | { readonly state: "completed" }
  | { readonly state: "failed"; readonly code: DaemonExecutionFailureCode };

export interface DaemonExecutionStatusRequest {
  readonly kind: "execution-status";
  readonly protocolVersion: number;
  readonly instanceId: string;
  readonly processToken: string;
  readonly requestId: string;
}

export interface DaemonExecutionStatusResponse {
  readonly kind: "execution-status";
  readonly instanceId: string;
  readonly processToken: string;
  readonly requestId: string;
  readonly status: DaemonExecutionStatus;
}

export interface DaemonResultChunk {
  readonly transferId: string;
  readonly requestId: string;
  readonly offset: number;
  readonly sequence: number;
  readonly stream: DaemonOutputStream;
  readonly bytes: Uint8Array;
}

export interface DaemonResultFetchRequest {
  readonly kind: "result-fetch";
  readonly protocolVersion: number;
  readonly instanceId: string;
  readonly processToken: string;
  readonly requestId: string;
  readonly offset: number;
}

export interface DaemonResultAcknowledgement {
  readonly kind: "result-ack";
  readonly protocolVersion: number;
  readonly instanceId: string;
  readonly processToken: string;
  readonly requestId: string;
  readonly transferId: string;
}

export interface DaemonWorkerPhaseDurations {
  readonly freshnessMs: number;
  readonly navigationMs: number;
  readonly renderMs: number;
  readonly workerOutputMs: number;
}

export interface DaemonRefreshSummary {
  readonly added: number;
  readonly changed: number;
  readonly removed: number;
  readonly unchanged: number;
}

export type DaemonExecutionOutcome = "completed" | "failed";
export type DaemonDeliveryOutcome = "delivered" | "disconnected" | "failed";
export type DaemonWorkerReplacementCause =
  | "hard-pressure"
  | "out-of-memory"
  | "shed-failure"
  | "worker-exit";

export interface DaemonStartupDiagnostic {
  readonly kind: "startup-completed";
  readonly workerGeneration: number;
  readonly fileCount: number;
  readonly discoveryMs: number;
  readonly indexingMs: number;
  readonly totalMs: number;
}

export type DaemonWorkerDiagnostic =
  | {
      readonly kind: "resources-released";
      readonly workerGeneration: number;
      readonly workerHeapUsedBytes: number;
      readonly workerHeapLimitBytes: number;
    }
  | {
      readonly kind: "worker-replaced";
      readonly cause: DaemonWorkerReplacementCause;
      readonly previousWorkerGeneration: number;
      readonly workerGeneration: number;
      readonly fileCount: number;
      readonly discoveryMs: number;
      readonly indexingMs: number;
      readonly totalMs: number;
    };

export interface DaemonShutdownDiagnostic {
  readonly kind: "shutdown";
  readonly reason: DaemonStopReason;
  readonly force: boolean;
}

export type DaemonOperationDiagnostic =
  | {
      readonly kind: "request-accepted";
      readonly requestId: string;
      readonly command: DaemonCommandName;
      readonly queueDepth: number;
      readonly workerGeneration: number;
    }
  | {
      readonly kind: "turn-started";
      readonly requestId: string;
      readonly queueWaitMs: number;
      readonly workerGeneration: number;
    }
  | ({
      readonly kind: "worker-completed";
      readonly requestId: string;
    } & DaemonWorkerPhaseDurations &
      DaemonRefreshSummary)
  | {
      readonly kind: "response-spooled";
      readonly requestId: string;
      readonly rawBytes: number;
      readonly recordCount: number;
      readonly spoolMs: number;
    }
  | {
      readonly kind: "execution-terminal";
      readonly requestId: string;
      readonly outcome: DaemonExecutionOutcome;
      readonly serviceMs: number;
      readonly processRssBytes?: number;
      readonly peakProcessRssBytes?: number;
      readonly peakWorkerHeapUsedBytes?: number;
      readonly workerHeapUsedBytes?: number;
      readonly spoolBytes?: number;
    }
  | { readonly kind: "client-disconnected"; readonly requestId: string }
  | { readonly kind: "client-reattached"; readonly requestId: string }
  | { readonly kind: "operation-trace-expired"; readonly requestId: string }
  | {
      readonly kind: "delivery-terminal";
      readonly requestId: string;
      readonly outcome: DaemonDeliveryOutcome;
      readonly deliveryMs: number;
    };

export type DaemonFailureOperation =
  | "start"
  | "request"
  | "resource-sample"
  | "resource-drain"
  | "worker-exit"
  | "worker-replacement"
  | "completion-delivery"
  | "completion-cleanup"
  | "transport-close"
  | "diagnostics-write"
  | "diagnostics-rotation";

export type DaemonDiagnosticErrorName =
  | "Error"
  | "TypeError"
  | "RangeError"
  | "SyntaxError"
  | "ReferenceError"
  | "DaemonNavigationWorkerExitedError"
  | "CompletionSpoolCapacityError"
  | "CompletionSpoolReadError"
  | "UnknownError";

export type DaemonDiagnosticFailureCode = DaemonExecutionFailureCode | "operation-failed";

export type DaemonProcessTerminationReason =
  | "uncaught-exception"
  | "unhandled-rejection"
  | "signal";

export type DaemonProcessTerminationSignal = "SIGTERM" | "SIGINT" | "SIGHUP";

export type DaemonDiagnosticEvent =
  | { readonly kind: "start" }
  | { readonly kind: "ready"; readonly fileCount: number }
  | { readonly kind: "acceptance"; readonly requestId: string; readonly queuePosition: number }
  | {
      readonly kind: "request";
      readonly command: DaemonCommandName;
      readonly durationMs: number;
      readonly exitCode: number;
    }
  | {
      readonly kind: "freshness";
      readonly added: number;
      readonly changed: number;
      readonly removed: number;
      readonly unchanged: number;
    }
  | { readonly kind: "stop"; readonly reason: DaemonStopReason }
  | { readonly kind: "diagnostics-dropped"; readonly droppedCount: number }
  | {
      readonly kind: "process-termination";
      readonly terminationReason: DaemonProcessTerminationReason;
      readonly signal?: DaemonProcessTerminationSignal;
      readonly errorName?: DaemonDiagnosticErrorName;
    }
  | {
      readonly kind: "failure";
      readonly operation: DaemonFailureOperation;
      readonly failureCode: DaemonDiagnosticFailureCode;
      readonly errorName: DaemonDiagnosticErrorName;
    }
  | DaemonStartupDiagnostic
  | DaemonWorkerDiagnostic
  | DaemonShutdownDiagnostic
  | DaemonOperationDiagnostic;

export type DaemonLogEvent = DaemonDiagnosticEvent & {
  readonly schemaVersion: 1;
  readonly timestamp: number;
  readonly instanceId: string;
  readonly workspaceKey: string;
};

export type DaemonLifecycleRequest =
  | {
      readonly kind: "identify";
      readonly instanceId: string;
      readonly processToken: string;
    }
  | {
      readonly kind: "terminate";
      readonly instanceId: string;
      readonly processToken: string;
    }
  | {
      readonly kind: "kill";
      readonly instanceId: string;
      readonly processToken: string;
    }
  | { readonly kind: "ping"; readonly protocolVersion: number; readonly instanceId: string }
  | { readonly kind: "stop"; readonly protocolVersion: number; readonly instanceId: string };

export type DaemonRequest =
  | DaemonLifecycleRequest
  | DaemonExecuteRequest
  | DaemonExecutionStatusRequest
  | DaemonResultFetchRequest
  | DaemonResultAcknowledgement;

export type DaemonLifecycleResponse =
  | {
      readonly kind: "identity";
      readonly instanceId: string;
      readonly processToken: string;
      readonly pid: number;
      readonly startedAt: number;
    }
  | {
      readonly kind: "terminating";
      readonly instanceId: string;
      readonly processToken: string;
    }
  | {
      readonly kind: "killing";
      readonly instanceId: string;
      readonly processToken: string;
    }
  | {
      readonly kind: "pong";
      readonly protocolVersion: number;
      readonly instanceId: string;
      readonly symnavVersion: string;
      readonly state?: "starting" | "ready" | "busy";
      readonly startedAt?: number;
      readonly fileCount?: number;
      readonly memoryBytes?: number;
      readonly lastNavigationAt?: number;
      readonly currentCommand?: string;
      readonly currentCommandElapsedMs?: number;
      readonly queued?: number;
      readonly activity?: DaemonActivitySnapshot;
    }
  | { readonly kind: "stopped"; readonly instanceId: string };

export type DaemonResponse =
  | DaemonLifecycleResponse
  | DaemonExecutionServerFrame
  | DaemonExecutionStatusResponse
  | {
      readonly kind: "result-acknowledged";
      readonly instanceId: string;
      readonly processToken: string;
      readonly requestId: string;
      readonly transferId: string;
    };

export type DaemonServerMessage = DaemonResponse | DaemonResultChunk;

export type DaemonPong = Extract<DaemonResponse, { readonly kind: "pong" }>;

export interface DaemonServer {
  close(force?: boolean): Promise<void>;
}

export type DaemonStartResult =
  | {
      readonly status: "ready";
      readonly workspaceRoot: string;
      readonly fileCount: number;
      readonly loadDurationMs: number;
    }
  | {
      readonly status: "already-running";
      readonly workspaceRoot: string;
      readonly pid: number;
      readonly uptimeMs: number;
    }
  | { readonly status: "disabled" };

