    process.execPath,
    [
      fileURLToPath(new URL("../../../node_modules/tsx/dist/cli.mjs", import.meta.url)),
      fileURLToPath(new URL("../../helpers/daemon-startup-publisher.ts", import.meta.url)),
      workspaceRoot,
      stateDirectory,
      readyPath,
      barrierPath,
      resultPath,
    ],
    { stdio: "ignore" },
  );
}

function spawnStuckDaemon(
